code.java:
public boolean isPrime(long n) {
    if (n < 2) return false;
    if (n < 4) return true;               // 2 and 3 are prime
    if (n % 2 == 0) return false;         // drop all evens > 2
    for (long i = 3; i * i <= n; i += 2) {// odd divisors up to sqrt(n)
        if (n % i == 0) return false;
    }
    return true;
}

// usage: System.out.println(isPrime(n) ? "Prime" : "Not prime");

code.python:
def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n < 4:
        return True                       # 2 and 3 are prime
    if n % 2 == 0:
        return False                      # drop all evens > 2
    i = 3
    while i * i <= n:                      # odd divisors up to sqrt(n)
        if n % i == 0:
            return False
        i += 2
    return True

# usage: print("Prime" if is_prime(n) else "Not prime")

